tool_schemas.implementation:
def Optional_Settings(action, workspace_id=None, user_id=None, jira_server_id=None, jira_auth_session_id=None, jira_credential_id=None, auth_type=None, status=None, q=None, limit=None, cursor=None, sort=None, jira_server=None, auth_session=None, credential=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0473000" if __import__("os").path.isdir("./environment_mix/0473000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()

    # ---------- constants ----------
    ACTIONS = {
        "list_jira_servers", "get_jira_server", "create_jira_server", "update_jira_server", "delete_jira_server",
        "start_auth_session", "get_auth_session", "cancel_auth_session", "complete_oauth_callback",
        "list_credentials", "get_credential", "revoke_credential", "verify_jira_server"
    }
    AUTH_TYPES = {"oauth2", "api_token_basic", "personal_access_token"}
    JRS_STATUSES = ["pending", "active", "revoked", "error", "deleted"]
    JRS_TRANSITIONS = {
        "pending": {"active", "error", "deleted"},
        "active": {"revoked", "error", "deleted"},
        "error": {"active", "revoked", "deleted"},
        "revoked": {"active", "deleted"},
        "deleted": set()
    }
    JAS_STATUSES = ["initiated", "awaiting_callback", "completed", "expired", "cancelled", "error"]
    JAS_TRANSITIONS = {
        "initiated": {"awaiting_callback", "cancelled", "expired", "error"},
        "awaiting_callback": {"completed", "cancelled", "expired", "error"},
        "completed": set(),
        "expired": set(),
        "cancelled": set(),
        "error": set()
    }
    JRC_STATUSES = ["active", "rotated", "revoked"]
    JRC_TRANSITIONS = {"active": {"rotated", "revoked"}, "rotated": {"revoked"}, "revoked": set()}
    SORT_ENUM = {"created_at", "-created_at", "updated_at", "-updated_at", "name", "-name", "last_verified_at", "-last_verified_at"}

    # ---------- request log / quota enforcement ----------
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_dir():
        try:
            os.makedirs(_DB, exist_ok=True)
        except Exception:
            pass

    def _load_logs():
        _ensure_dir()
        logs = _load("request_logs.json")
        if isinstance(logs, dict):
            # tolerate old format
            logs = logs.get("logs", [])
        if not isinstance(logs, list):
            logs = []
        return logs

    def _save_logs(logs):
        _save("request_logs.json", logs)

    def _rate_limit_check():
        # Simple observed dynamics with small defaults:
        # - Rate limit: 120 requests / rolling minute
        # - Daily quota: 5000 requests / rolling 24h
        logs = _load_logs()
        now = datetime.datetime.utcnow()
        one_min_ago = now - datetime.timedelta(seconds=60)
        day_ago = now - datetime.timedelta(hours=24)

        def _ts_ok(row):
            t = _parse_dt(row.get("timestamp"))
            return t

        per_min = 0
        per_day = 0
        for r in logs[-20000:]:
            t = _ts_ok(r)
            if not t:
                continue
            if t >= one_min_ago:
                per_min += 1
            if t >= day_ago:
                per_day += 1

        if per_min >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=120)
        if per_day >= 5000:
            return _err("QUOTA_EXCEEDED", "Request quota exceeded for the last 24 hours.", quota_24h=5000)
        return None

    def _log_call(endpoint, used_credential_id, status_code, error_code=None):
        logs = _load_logs()
        row = {
            "id": "rql_" + secrets.token_hex(8).upper(),
            "endpoint": endpoint,
            "action": action,
            "workspace_id": workspace_id,
            "user_id": user_id,
            "jira_server_id": jira_server_id,
            "jira_auth_session_id": jira_auth_session_id,
            "jira_credential_id": used_credential_id,
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": int(max(0, round((time.time() - _t0) * 1000))),
            "timestamp": _now()
        }
        logs.append(row)
        _save_logs(logs)

    # Pre-check action validity and rate limits (still logged on failure).
    endpoint_name = "Optional Settings"
    if action not in ACTIONS:
        _log_call(endpoint_name, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid action.", allowed=sorted(ACTIONS))
    rl = _rate_limit_check()
    if rl:
        _log_call(endpoint_name, None, 429, rl["error"]["code"])
        return rl

    # ---------- load collections ----------
    workspaces = _load("workspaces.json")
    users = _load("users.json")
    jira_servers = _load("jira_servers.json")
    jira_auth_sessions = _load("jira_auth_sessions.json")
    jira_credentials = _load("jira_credentials.json")

    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(users, list): users = []
    if not isinstance(jira_servers, list): jira_servers = []
    if not isinstance(jira_auth_sessions, list): jira_auth_sessions = []
    if not isinstance(jira_credentials, list): jira_credentials = []

    # ---------- validators/helpers ----------
    def _is_str(x): return isinstance(x, str)
    def _nonempty_str(x): return isinstance(x, str) and x.strip() != ""

    def _match(pattern, val):
        return isinstance(val, str) and re.match(pattern, val) is not None

    def _find_by_id(rows, rid):
        for r in rows:
            if r.get("id") == rid:
                return r
        return None

    def _normalize_base_url(u):
        # scheme + host (plus optional port), no path/query/fragment, no trailing slash
        if not _nonempty_str(u):
            return None
        s = u.strip()
        # If missing scheme, reject (schema says base_url includes scheme)
        m = re.match(r"^(https?)://([^/?#]+)(?:[/?#].*)?$", s, re.IGNORECASE)
        if not m:
            return None
        scheme = m.group(1).lower()
        host = m.group(2).strip().lower()
        host = host.rstrip("/")
        return f"{scheme}://{host}"

    def _gen_id(prefix):
        return f"{prefix}_{secrets.token_hex(8).upper()}"

    def _workspace_or_pick(wid):
        if wid is not None:
            if not _match(r"^wrk_[0-9A-Z]{4,}$", wid):
                return None, _err("VALIDATION_ERROR", "workspace_id is invalid.", field="workspace_id")
            ws = _find_by_id(workspaces, wid)
            if not ws:
                return None, _err("NOT_FOUND", "Workspace not found.", workspace_id=wid)
            return ws, None
        # Ambient auth: choose any non-deleted workspace (prefer active) that can serve
        candidates = [w for w in workspaces if w.get("status") in ("active", "suspended")]
        if not candidates:
            return None, _err("UNAUTHORIZED", "No workspace context available.")
        # Prefer active
        candidates.sort(key=lambda w: (0 if w.get("status") == "active" else 1, w.get("created_at") or ""))
        return candidates[0], None

    def _user_or_none(uid, wsid):
        if uid is None:
            return None, None
        if not _match(r"^usr_[0-9A-Z]{4,}$", uid):
            return None, _err("VALIDATION_ERROR", "user_id is invalid.", field="user_id")
        u = _find_by_id(users, uid)
        if not u:
            return None, _err("NOT_FOUND", "User not found.", user_id=uid)
        if u.get("workspace_id") != wsid:
            return None, _err("CONFLICT", "User does not belong to workspace.", user_id=uid, workspace_id=wsid)
        return u, None

    def _expire_auth_sessions_for_workspace(wsid=None):
        now = datetime.datetime.utcnow()
        changed = False
        for s in jira_auth_sessions:
            if wsid is not None and s.get("workspace_id") != wsid:
                continue
            st = s.get("status")
            exp = _parse_dt(s.get("expires_at"))
            if exp and exp <= now and st in ("initiated", "awaiting_callback"):
                # transition to expired if allowed
                if "expired" in JAS_TRANSITIONS.get(st, set()):
                    s["status"] = "expired"
                    s["updated_at"] = _now()
                    changed = True
        return changed

    def _has_active_credential_for_server(server_id):
        for c in jira_credentials:
            if c.get("jira_server_id") == server_id and c.get("status") == "active":
                return True
        return False

    def _server_effective_status_on_revoke(server_id):
        # If any active credential remains, server may stay active/error/pending; rule says revoke transitions to revoked unless another active exists.
        return "revoked" if not _has_active_credential_for_server(server_id) else None

    def _encrypt_secret(plaintext, scope_key):
        # Not real encryption; deterministic-at-rest transform to ensure plaintext is not persisted.
        # Store: "enc:v1:<b64(xor(plaintext, sha256(scope_key)))>"
        if plaintext is None:
            return None
        if not isinstance(plaintext, str) or plaintext == "":
            return None
        key = hashlib.sha256(scope_key.encode("utf-8")).digest()
        pt = plaintext.encode("utf-8")
        ct = bytes([pt[i] ^ key[i % len(key)] for i in range(len(pt))])
        return "enc:v1:" + base64.urlsafe_b64encode(ct).decode("ascii")

    def _validate_list_pagination():
        if limit is not None:
            if not isinstance(limit, int):
                return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
            if limit < 1 or limit > 200:
                return _err("VALIDATION_ERROR", "limit out of range.", field="limit", minimum=1, maximum=200)
        if cursor is not None and not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        if sort is not None and sort not in SORT_ENUM:
            return _err("VALIDATION_ERROR", "Invalid sort.", field="sort", allowed=sorted(SORT_ENUM))
        if q is not None and not isinstance(q, str):
            return _err("VALIDATION_ERROR", "q must be a string.", field="q")
        if status is not None and not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.", field="status")
        return None

    def _apply_sort(rows, sort_key):
        if not sort_key:
            sort_key = "-updated_at"
        desc = sort_key.startswith("-")
        key = sort_key[1:] if desc else sort_key

        def _k(r):
            v = r.get(key)
            if v is None:
                return "" if key in ("name",) else "0000-00-00T00:00:00Z"
            return v
        rows.sort(key=_k, reverse=desc)

    def _paginate(rows, lim, cur):
        lim = 50 if lim is None else lim
        start = 0
        if cur:
            # cursor is base64 of "offset:<int>"
            try:
                raw = base64.urlsafe_b64decode(cur.encode("ascii")).decode("utf-8")
                if raw.startswith("offset:"):
                    start = int(raw.split(":", 1)[1])
            except Exception:
                start = 0
        end = start + lim
        page = rows[start:end]
        next_cursor = None
        has_more = end < len(rows)
        if has_more:
            next_cursor = base64.urlsafe_b64encode(f"offset:{end}".encode("utf-8")).decode("ascii")
        return page, {"limit": lim, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

    # ---------- resolve context ----------
    ws, e = _workspace_or_pick(workspace_id)
    if e:
        _log_call(endpoint_name, None, 400 if e["error"]["code"] == "VALIDATION_ERROR" else 404, e["error"]["code"])
        return e
    workspace_id = ws.get("id")

    # Expire sessions as required (observable and persisted if changed)
    expired_changed = _expire_auth_sessions_for_workspace(workspace_id)
    if expired_changed:
        _save("jira_auth_sessions.json", jira_auth_sessions)

    u, e = _user_or_none(user_id, workspace_id)
    if e:
        _log_call(endpoint_name, None, 400 if e["error"]["code"] == "VALIDATION_ERROR" else 404, e["error"]["code"])
        return e

    # Workspace deleted restriction for create/mutation types
    def _deny_if_workspace_deleted():
        if ws.get("status") == "deleted":
            return _err("INVALID_TRANSITION", "Workspace is deleted and cannot create or mutate Jira settings.", workspace_id=workspace_id)
        return None

    # ---------- action handlers ----------
    try:
        if action == "list_jira_servers":
            ve = _validate_list_pagination()
            if ve:
                _log_call(endpoint_name, None, 400, ve["error"]["code"])
                return ve

            rows = [r for r in jira_servers if r.get("workspace_id") == workspace_id and r.get("status") != "deleted"]
            if status:
                rows = [r for r in rows if r.get("status") == status]
            if q:
                ql = q.strip().lower()
                rows = [r for r in rows if ql in (r.get("name") or "").lower() or ql in (r.get("base_url") or "").lower()]

            _apply_sort(rows, sort)
            page, meta = _paginate(rows, limit, cursor)

            out = {"jira_servers": page, **meta}
            _log_call(endpoint_name, None, 200, None)
            return out

        if action == "get_jira_server":
            if not _match(r"^jrs_[0-9A-Z]{4,}$", jira_server_id or ""):
                e = _err("VALIDATION_ERROR", "jira_server_id is required and must be valid.", field="jira_server_id")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            r = _find_by_id(jira_servers, jira_server_id)
            if not r or r.get("workspace_id") != workspace_id or r.get("status") == "deleted":
                e = _err("NOT_FOUND", "Jira server not found.", jira_server_id=jira_server_id)
                _log_call(endpoint_name, None, 404, e["error"]["code"])
                return e
            _log_call(endpoint_name, None, 200, None)
            return {"jira_server": r}

        if action == "create_jira_server":
            de = _deny_if_workspace_deleted()
            if de:
                _log_call(endpoint_name, None, 409, de["error"]["code"])
                return de
            if not isinstance(jira_server, dict):
                e = _err("VALIDATION_ERROR", "jira_server body is required.", field="jira_server")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e

            name = jira_server.get("name")
            base_url = jira_server.get("base_url")
            deployment_type = jira_server.get("deployment_type")
            at = jira_server.get("auth_type")
            st = jira_server.get("status") or "pending"
            last_error = jira_server.get("last_error")

            if not _nonempty_str(name):
                e = _err("VALIDATION_ERROR", "jira_server.name is required.", field="jira_server.name")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            norm = _normalize_base_url(base_url)
            if not norm:
                e = _err("VALIDATION_ERROR", "jira_server.base_url must be a valid http(s) URL (scheme + host).", field="jira_server.base_url")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            if deployment_type not in ("cloud", "server", "data_center"):
                e = _err("VALIDATION_ERROR", "Invalid deployment_type.", field="jira_server.deployment_type")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            if at not in AUTH_TYPES:
                e = _err("VALIDATION_ERROR", "Invalid auth_type.", field="jira_server.auth_type")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            if st not in JRS_STATUSES:
                e = _err("VALIDATION_ERROR", "Invalid status.", field="jira_server.status")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            # Only allow creating as pending/error; "active" requires active credentials, but none can exist yet.
            if st == "active":
                e = _err("INVALID_TRANSITION", "Cannot create Jira server as active without active credentials.")
                _log_call(endpoint_name, None, 409, e["error"]["code"])
                return e

            # uniqueness: (workspace_id, base_url) and (workspace_id, name)
            for r in jira_servers:
                if r.get("workspace_id") != workspace_id or r.get("status") == "deleted":
                    continue
                if (r.get("base_url") or "").lower() == norm.lower():
                    e = _err("CONFLICT", "A Jira server with this base_url already exists in the workspace.", base_url=norm)
                    _log_call(endpoint_name, None, 409, e["error"]["code"])
                    return e
                if (r.get("name") or "").strip().lower() == name.strip().lower():
                    e = _err("CONFLICT", "A Jira server with this name already exists in the workspace.", name=name)
                    _log_call(endpoint_name, None, 409, e["error"]["code"])
                    return e

            now = _now()
            new_row = {
                "id": _gen_id("jrs"),
                "workspace_id": workspace_id,
                "name": name.strip(),
                "base_url": norm,
                "deployment_type": deployment_type,
                "auth_type": at,
                "status": st,
                "last_verified_at": None,
                "last_error": last_error if isinstance(last_error, str) else None,
                "created_by_user_id": u.get("id") if u else None,
                "created_at": now,
                "updated_at": now
            }
            jira_servers.append(new_row)
            _save("jira_servers.json", jira_servers)
            _log_call(endpoint_name, None, 201, None)
            return {"jira_server": new_row}

        if action == "update_jira_server":
            de = _deny_if_workspace_deleted()
            if de:
                _log_call(endpoint_name, None, 409, de["error"]["code"])
                return de
            if not _match(r"^jrs_[0-9A-Z]{4,}$", jira_server_id or ""):
                e = _err("VALIDATION_ERROR", "jira_server_id is required and must be valid.", field="jira_server_id")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            if not isinstance(jira_server, dict):
                e = _err("VALIDATION_ERROR", "jira_server body is required.", field="jira_server")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e

            r = _find_by_id(jira_servers, jira_server_id)
            if not r or r.get("workspace_id") != workspace_id or r.get("status") == "deleted":
                e = _err("NOT_FOUND", "Jira server not found.", jira_server_id=jira_server_id)
                _log_call(endpoint_name, None, 404, e["error"]["code"])
                return e

            new_name = jira_server.get("name", r.get("name"))
            new_base = jira_server.get("base_url", r.get("base_url"))
            new_dep = jira_server.get("deployment_type", r.get("deployment_type"))
            new_at = jira_server.get("auth_type", r.get("auth_type"))
            new_st = jira_server.get("status", r.get("status"))
            new_last_error = jira_server.get("last_error", r.get("last_error"))

            if not _nonempty_str(new_name):
                e = _err("VALIDATION_ERROR", "jira_server.name cannot be empty.", field="jira_server.name")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            norm = _normalize_base_url(new_base)
            if not norm:
                e = _err("VALIDATION_ERROR", "jira_server.base_url must be a valid http(s) URL (scheme + host).", field="jira_server.base_url")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            if new_dep not in ("cloud", "server", "data_center"):
                e = _err("VALIDATION_ERROR", "Invalid deployment_type.", field="jira_server.deployment_type")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            if new_at not in AUTH_TYPES:
                e = _err("VALIDATION_ERROR", "Invalid auth_type.", field="jira_server.auth_type")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            if new_st not in JRS_STATUSES:
                e = _err("VALIDATION_ERROR", "Invalid status.", field="jira_server.status")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e

            # uniqueness checks if changing name/base_url
            for other in jira_servers:
                if other.get("id") == r.get("id"):
                    continue
                if other.get("workspace_id") != workspace_id or other.get("status") == "deleted":
                    continue
                if (other.get("base_url") or "").lower() == norm.lower():
                    e = _err("CONFLICT", "A Jira server with this base_url already exists in the workspace.", base_url=norm)
                    _log_call(endpoint_name, None, 409, e["error"]["code"])
                    return e
                if (other.get("name") or "").strip().lower() == new_name.strip().lower():
                    e = _err("CONFLICT", "A Jira server with this name already exists in the workspace.", name=new_name)
                    _log_call(endpoint_name, None, 409, e["error"]["code"])
                    return e

            # status transition enforcement
            old_st = r.get("status")
            if new_st != old_st:
                if new_st not in JRS_TRANSITIONS.get(old_st, set()):
                    e = _err("INVALID_TRANSITION", "Illegal Jira server status transition.", from_status=old_st, to_status=new_st)
                    _log_call(endpoint_name, None, 409, e["error"]["code"])
                    return e
                if new_st == "active" and not _has_active_credential_for_server(r.get("id")):
                    e = _err("INVALID_TRANSITION", "Cannot activate Jira server without at least one active credential.", jira_server_id=r.get("id"))
                    _log_call(endpoint_name, None, 409, e["error"]["code"])
                    return e

            r["name"] = new_name.strip()
            r["base_url"] = norm
            r["deployment_type"] = new_dep
            r["auth_type"] = new_at
            r["status"] = new_st
            r["last_error"] = new_last_error if isinstance(new_last_error, str) else None
            r["updated_at"] = _now()
            _save("jira_servers.json", jira_servers)
            _log_call(endpoint_name, None, 200, None)
            return {"jira_server": r}

        if action == "delete_jira_server":
            de = _deny_if_workspace_deleted()
            if de:
                _log_call(endpoint_name, None, 409, de["error"]["code"])
                return de
            if not _match(r"^jrs_[0-9A-Z]{4,}$", jira_server_id or ""):
                e = _err("VALIDATION_ERROR", "jira_server_id is required and must be valid.", field="jira_server_id")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            r = _find_by_id(jira_servers, jira_server_id)
            if not r or r.get("workspace_id") != workspace_id or r.get("status") == "deleted":
                e = _err("NOT_FOUND", "Jira server not found.", jira_server_id=jira_server_id)
                _log_call(endpoint_name, None, 404, e["error"]["code"])
                return e
            old_st = r.get("status")
            if "deleted" not in JRS_TRANSITIONS.get(old_st, set()):
                e = _err("INVALID_TRANSITION", "Cannot delete Jira server from current status.", from_status=old_st)
                _log_call(endpoint_name, None, 409, e["error"]["code"])
                return e
            r["status"] = "deleted"
            r["updated_at"] = _now()

            # revoke credentials for this server
            changed_cred = False
            for c in jira_credentials:
                if c.get("jira_server_id") == jira_server_id and c.get("status") != "revoked":
                    # transition to revoked if allowed
                    if "revoked" in JRC_TRANSITIONS.get(c.get("status"), set()) or c.get("status") == "active":
                        c["status"] = "revoked"
                        c["updated_at"] = _now()
                        changed_cred = True

            _save("jira_servers.json", jira_servers)
            if changed_cred:
                _save("jira_credentials.json", jira_credentials)

            _log_call(endpoint_name, None, 200, None)
            return {"jira_server": r}

        if action == "start_auth_session":
            de = _deny_if_workspace_deleted()
            if de:
                _log_call(endpoint_name, None, 409, de["error"]["code"])
                return de
            if auth_type is None:
                e = _err("VALIDATION_ERROR", "auth_type is required.", field="auth_type")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            if auth_type not in AUTH_TYPES:
                e = _err("VALIDATION_ERROR", "Invalid auth_type.", field="auth_type")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            if auth_session is not None and not isinstance(auth_session, dict):
                e = _err("VALIDATION_ERROR", "auth_session must be an object.", field="auth_session")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            auth_session = auth_session or {}
            redirect_uri = auth_session.get("redirect_uri")
            state_token = auth_session.get("state_token") or ("st_" + secrets.token_urlsafe(18))

            if redirect_uri is not None and not isinstance(redirect_uri, str):
                e = _err("VALIDATION_ERROR", "auth_session.redirect_uri must be a string.", field="auth_session.redirect_uri")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            if not _nonempty_str(state_token):
                e = _err("VALIDATION_ERROR", "auth_session.state_token must be a non-empty string.", field="auth_session.state_token")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            # unique(state_token)
            for s in jira_auth_sessions:
                if s.get("state_token") == state_token:
                    e = _err("CONFLICT", "state_token already exists.", state_token=state_token)
                    _log_call(endpoint_name, None, 409, e["error"]["code"])
                    return e

            now_dt = datetime.datetime.utcnow().replace(microsecond=0)
            expires_at = (now_dt + datetime.timedelta(minutes=10)).isoformat() + "Z"
            now = _now()

            new_sess = {
                "id": _gen_id("jas"),
                "workspace_id": workspace_id,
                "user_id": u.get("id") if u else None,
                "jira_server_id": jira_server_id if jira_server_id else None,
                "auth_type": auth_type,
                "status": "awaiting_callback" if auth_type == "oauth2" else "initiated",
                "state_token": state_token,
                "redirect_uri": redirect_uri,
                "expires_at": expires_at,
                "error_code": None,
                "error_message": None,
                "created_at": now,
                "updated_at": now
            }
            jira_auth_sessions.append(new_sess)
            _save("jira_auth_sessions.json", jira_auth_sessions)
            _log_call(endpoint_name, None, 201, None)
            return {"auth_session": new_sess}

        if action == "get_auth_session":
            if not _match(r"^jas_[0-9A-Z]{4,}$", jira_auth_session_id or ""):
                e = _err("VALIDATION_ERROR", "jira_auth_session_id is required and must be valid.", field="jira_auth_session_id")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            s = _find_by_id(jira_auth_sessions, jira_auth_session_id)
            if not s or s.get("workspace_id") != workspace_id:
                e = _err("NOT_FOUND", "Auth session not found.", jira_auth_session_id=jira_auth_session_id)
                _log_call(endpoint_name, None, 404, e["error"]["code"])
                return e
            _log_call(endpoint_name, None, 200, None)
            return {"auth_session": s}

        if action == "cancel_auth_session":
            de = _deny_if_workspace_deleted()
            if de:
                _log_call(endpoint_name, None, 409, de["error"]["code"])
                return de
            if not _match(r"^jas_[0-9A-Z]{4,}$", jira_auth_session_id or ""):
                e = _err("VALIDATION_ERROR", "jira_auth_session_id is required and must be valid.", field="jira_auth_session_id")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            s = _find_by_id(jira_auth_sessions, jira_auth_session_id)
            if not s or s.get("workspace_id") != workspace_id:
                e = _err("NOT_FOUND", "Auth session not found.", jira_auth_session_id=jira_auth_session_id)
                _log_call(endpoint_name, None, 404, e["error"]["code"])
                return e
            old = s.get("status")
            if "cancelled" not in JAS_TRANSITIONS.get(old, set()):
                # idempotent: if already cancelled/terminal, return it
                if old in ("cancelled", "completed", "expired", "error"):
                    _log_call(endpoint_name, None, 200, None)
                    return {"auth_session": s}
                e = _err("INVALID_TRANSITION", "Cannot cancel auth session from current status.", from_status=old)
                _log_call(endpoint_name, None, 409, e["error"]["code"])
                return e
            s["status"] = "cancelled"
            s["updated_at"] = _now()
            _save("jira_auth_sessions.json", jira_auth_sessions)
            _log_call(endpoint_name, None, 200, None)
            return {"auth_session": s}

        if action == "complete_oauth_callback":
            de = _deny_if_workspace_deleted()
            if de:
                _log_call(endpoint_name, None, 409, de["error"]["code"])
                return de
            if not _match(r"^jas_[0-9A-Z]{4,}$", jira_auth_session_id or ""):
                e = _err("VALIDATION_ERROR", "jira_auth_session_id is required and must be valid.", field="jira_auth_session_id")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            if auth_session is not None and not isinstance(auth_session, dict):
                e = _err("VALIDATION_ERROR", "auth_session must be an object.", field="auth_session")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            auth_session = auth_session or {}
            s = _find_by_id(jira_auth_sessions, jira_auth_session_id)
            if not s or s.get("workspace_id") != workspace_id:
                e = _err("NOT_FOUND", "Auth session not found.", jira_auth_session_id=jira_auth_session_id)
                _log_call(endpoint_name, None, 404, e["error"]["code"])
                return e

            # expire check already done globally, but ensure not completing expired
            exp = _parse_dt(s.get("expires_at"))
            if exp and exp <= datetime.datetime.utcnow():
                if s.get("status") in ("initiated", "awaiting_callback"):
                    s["status"] = "expired"
                    s["updated_at"] = _now()
                    _save("jira_auth_sessions.json", jira_auth_sessions)
                e = _err("INVALID_TRANSITION", "Auth session is expired and cannot be completed.", jira_auth_session_id=jira_auth_session_id)
                _log_call(endpoint_name, None, 409, e["error"]["code"])
                return e

            if s.get("auth_type") != "oauth2":
                e = _err("VALIDATION_ERROR", "Auth session is not an OAuth2 session.", jira_auth_session_id=jira_auth_session_id)
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e

            old = s.get("status")
            if old not in ("awaiting_callback", "initiated"):
                # idempotent: if already completed, return session
                if old == "completed":
                    _log_call(endpoint_name, None, 200, None)
                    return {"auth_session": s}
                e = _err("INVALID_TRANSITION", "Cannot complete auth session from current status.", from_status=old)
                _log_call(endpoint_name, None, 409, e["error"]["code"])
                return e

            provided_state = auth_session.get("state_token")
            if provided_state is not None and not isinstance(provided_state, str):
                e = _err("VALIDATION_ERROR", "auth_session.state_token must be a string.", field="auth_session.state_token")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            if provided_state and provided_state != s.get("state_token"):
                e = _err("UNAUTHORIZED", "state_token mismatch.")
                _log_call(endpoint_name, None, 401, e["error"]["code"])
                return e

            cb_error_code = auth_session.get("error_code")
            cb_error_message = auth_session.get("error_message")
            code = auth_session.get("code")

            if cb_error_code or cb_error_message:
                if "error" not in JAS_TRANSITIONS.get(old, set()):
                    e = _err("INVALID_TRANSITION", "Cannot mark session as error from current status.", from_status=old)
                    _log_call(endpoint_name, None, 409, e["error"]["code"])
                    return e
                s["status"] = "error"
                s["error_code"] = cb_error_code if isinstance(cb_error_code, str) else "oauth_error"
                s["error_message"] = cb_error_message if isinstance(cb_error_message, str) else None
                s["updated_at"] = _now()
                _save("jira_auth_sessions.json", jira_auth_sessions)
                _log_call(endpoint_name, None, 200, None)
                return {"auth_session": s}

            if not _nonempty_str(code):
                e = _err("VALIDATION_ERROR", "auth_session.code is required to complete OAuth callback.", field="auth_session.code")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e

            # Determine / create jira_server if needed: driven by stored session / server-side config only.
            # If session already has jira_server_id, use it; else pick a pending server in workspace matching oauth2.
            target_server = None
            if s.get("jira_server_id"):
                target_server = _find_by_id(jira_servers, s.get("jira_server_id"))
                if not target_server or target_server.get("workspace_id") != workspace_id or target_server.get("status") == "deleted":
                    e = _err("NOT_FOUND", "Target Jira server for session not found.", jira_server_id=s.get("jira_server_id"))
                    _log_call(endpoint_name, None, 404, e["error"]["code"])
                    return e
            else:
                candidates = [r for r in jira_servers if r.get("workspace_id") == workspace_id and r.get("status") in ("pending", "error", "revoked", "active") and r.get("auth_type") == "oauth2"]
                # pick most recently updated
                candidates.sort(key=lambda rr: rr.get("updated_at") or "", reverse=True)
                if candidates:
                    target_server = candidates[0]
                    s["jira_server_id"] = target_server.get("id")

            if not target_server:
                # Create a server record in pending based on server-side defaults (minimal viable).
                now = _now()
                target_server = {
                    "id": _gen_id("jrs"),
                    "workspace_id": workspace_id,
                    "name": "Jira (OAuth2)",
                    "base_url": "https://unknown.invalid",
                    "deployment_type": "cloud",
                    "auth_type": "oauth2",
                    "status": "pending",
                    "last_verified_at": None,
                    "last_error": None,
                    "created_by_user_id": s.get("user_id"),
                    "created_at": now,
                    "updated_at": now
                }
                jira_servers.append(target_server)
                s["jira_server_id"] = target_server["id"]

            # Persist credential row (store encrypted secret derived from code; no plaintext persisted)
            # Rotate any prior active credential for (server, user, oauth2)
            bound_user_id = s.get("user_id")
            # uniqueness active: (jira_server_id, user_id, auth_type, status='active')
            for c in jira_credentials:
                if c.get("jira_server_id") == target_server["id"] and c.get("user_id") == bound_user_id and c.get("auth_type") == "oauth2" and c.get("status") == "active":
                    c["status"] = "rotated"
                    c["updated_at"] = _now()

            now = _now()
            cred_id = _gen_id("jrc")
            access_token_enc = _encrypt_secret("access:" + code, f"{workspace_id}:{target_server['id']}:{cred_id}")
            refresh_token_enc = _encrypt_secret("refresh:" + code, f"{workspace_id}:{target_server['id']}:{cred_id}:r")
            new_cred = {
                "id": cred_id,
                "jira_server_id": target_server["id"],
                "workspace_id": workspace_id,
                "user_id": bound_user_id,
                "auth_type": "oauth2",
                "status": "active",
                "account_id": None,
                "username": None,
                "access_token_enc": access_token_enc,
                "refresh_token_enc": refresh_token_enc,
                "api_token_enc": None,
                "token_expires_at": (datetime.datetime.utcnow().replace(microsecond=0) + datetime.timedelta(hours=1)).isoformat() + "Z",
                "scopes": (credential.get("scopes") if isinstance(credential, dict) and isinstance(credential.get("scopes"), list) else None),
                "last_used_at": None,
                "created_at": now,
                "updated_at": now
            }
            jira_credentials.append(new_cred)

            # complete session
            if "completed" not in JAS_TRANSITIONS.get(old, set()):
                e = _err("INVALID_TRANSITION", "Cannot complete auth session from current status.", from_status=old)
                _log_call(endpoint_name, None, 409, e["error"]["code"])
                return e
            s["status"] = "completed"
            s["error_code"] = None
            s["error_message"] = None
            s["updated_at"] = _now()

            # Activate server if allowed (must have active credential, now true)
            if target_server.get("status") != "active":
                if "active" in JRS_TRANSITIONS.get(target_server.get("status"), set()):
                    target_server["status"] = "active"
                target_server["last_error"] = None
                target_server["updated_at"] = _now()
                target_server["last_verified_at"] = _now()

            _save("jira_servers.json", jira_servers)
            _save("jira_credentials.json", jira_credentials)
            _save("jira_auth_sessions.json", jira_auth_sessions)

            _log_call(endpoint_name, new_cred["id"], 200, None)
            return {"auth_session": s, "jira_server": target_server, "credential": new_cred}

        if action == "list_credentials":
            ve = _validate_list_pagination()
            if ve:
                _log_call(endpoint_name, None, 400, ve["error"]["code"])
                return ve

            rows = [c for c in jira_credentials if c.get("workspace_id") == workspace_id]
            if jira_server_id:
                if not _match(r"^jrs_[0-9A-Z]{4,}$", jira_server_id):
                    e = _err("VALIDATION_ERROR", "jira_server_id is invalid.", field="jira_server_id")
                    _log_call(endpoint_name, None, 400, e["error"]["code"])
                    return e
                rows = [c for c in rows if c.get("jira_server_id") == jira_server_id]
            if user_id:
                rows = [c for c in rows if c.get("user_id") == user_id]
            if auth_type:
                if auth_type not in AUTH_TYPES:
                    e = _err("VALIDATION_ERROR", "Invalid auth_type.", field="auth_type")
                    _log_call(endpoint_name, None, 400, e["error"]["code"])
                    return e
                rows = [c for c in rows if c.get("auth_type") == auth_type]
            if status:
                rows = [c for c in rows if c.get("status") == status]

            # sort: reuse sort field; credentials have created_at/updated_at; ignore name/last_verified_at gracefully
            srt = sort if sort in SORT_ENUM else "-updated_at"
            key = srt[1:] if srt.startswith("-") else srt
            desc = srt.startswith("-")

            def _k(c):
                v = c.get(key)
                return v if v is not None else "0000-00-00T00:00:00Z"

            rows.sort(key=_k, reverse=desc)
            page, meta = _paginate(rows, limit, cursor)

            _log_call(endpoint_name, None, 200, None)
            return {"credentials": page, **meta}

        if action == "get_credential":
            if not _match(r"^jrc_[0-9A-Z]{4,}$", jira_credential_id or ""):
                e = _err("VALIDATION_ERROR", "jira_credential_id is required and must be valid.", field="jira_credential_id")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            c = _find_by_id(jira_credentials, jira_credential_id)
            if not c or c.get("workspace_id") != workspace_id:
                e = _err("NOT_FOUND", "Credential not found.", jira_credential_id=jira_credential_id)
                _log_call(endpoint_name, None, 404, e["error"]["code"])
                return e
            _log_call(endpoint_name, c.get("id"), 200, None)
            return {"credential": c}

        if action == "revoke_credential":
            de = _deny_if_workspace_deleted()
            if de:
                _log_call(endpoint_name, None, 409, de["error"]["code"])
                return de
            if not _match(r"^jrc_[0-9A-Z]{4,}$", jira_credential_id or ""):
                e = _err("VALIDATION_ERROR", "jira_credential_id is required and must be valid.", field="jira_credential_id")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            c = _find_by_id(jira_credentials, jira_credential_id)
            if not c or c.get("workspace_id") != workspace_id:
                e = _err("NOT_FOUND", "Credential not found.", jira_credential_id=jira_credential_id)
                _log_call(endpoint_name, None, 404, e["error"]["code"])
                return e

            old = c.get("status")
            if old == "revoked":
                # idempotent
                _log_call(endpoint_name, c.get("id"), 200, None)
                return {"credential": c}

            if "revoked" not in JRC_TRANSITIONS.get(old, set()):
                e = _err("INVALID_TRANSITION", "Cannot revoke credential from current status.", from_status=old)
                _log_call(endpoint_name, None, 409, e["error"]["code"])
                return e

            c["status"] = "revoked"
            c["updated_at"] = _now()

            # Transition server to revoked unless another active credential exists
            srv = _find_by_id(jira_servers, c.get("jira_server_id"))
            if srv and srv.get("workspace_id") == workspace_id and srv.get("status") != "deleted":
                new_srv_status = _server_effective_status_on_revoke(srv.get("id"))
                if new_srv_status and new_srv_status != srv.get("status"):
                    if new_srv_status in JRS_TRANSITIONS.get(srv.get("status"), set()):
                        srv["status"] = new_srv_status
                        srv["updated_at"] = _now()

            _save("jira_credentials.json", jira_credentials)
            _save("jira_servers.json", jira_servers)
            _log_call(endpoint_name, c.get("id"), 200, None)
            return {"credential": c, "jira_server": srv}

        if action == "verify_jira_server":
            de = _deny_if_workspace_deleted()
            if de:
                _log_call(endpoint_name, None, 409, de["error"]["code"])
                return de
            if not _match(r"^jrs_[0-9A-Z]{4,}$", jira_server_id or ""):
                e = _err("VALIDATION_ERROR", "jira_server_id is required and must be valid.", field="jira_server_id")
                _log_call(endpoint_name, None, 400, e["error"]["code"])
                return e
            srv = _find_by_id(jira_servers, jira_server_id)
            if not srv or srv.get("workspace_id") != workspace_id or srv.get("status") == "deleted":
                e = _err("NOT_FOUND", "Jira server not found.", jira_server_id=jira_server_id)
                _log_call(endpoint_name, None, 404, e["error"]["code"])
                return e

            # A "verify" succeeds iff at least one active credential exists.
            if not _has_active_credential_for_server(jira_server_id):
                srv["last_verified_at"] = None
                srv["last_error"] = "No active credentials available for this Jira server."
                # If active without credentials, force to error
                if srv.get("status") == "active" and "error" in JRS_TRANSITIONS.get("active", set()):
                    srv["status"] = "error"
                srv["updated_at"] = _now()
                _save("jira_servers.json", jira_servers)
                e = _err("CONFLICT", "Verification failed: no active credentials.", jira_server_id=jira_server_id)
                _log_call(endpoint_name, None, 409, e["error"]["code"])
                return e

            # Mark verified and activate if possible
            srv["last_verified_at"] = _now()
            srv["last_error"] = None
            if srv.get("status") in ("pending", "error", "revoked"):
                if "active" in JRS_TRANSITIONS.get(srv.get("status"), set()):
                    srv["status"] = "active"
            srv["updated_at"] = _now()

            # Update last_used_at on one active credential (most recently updated)
            actives = [c for c in jira_credentials if c.get("jira_server_id") == jira_server_id and c.get("status") == "active"]
            actives.sort(key=lambda cc: cc.get("updated_at") or "", reverse=True)
            used = None
            if actives:
                used = actives[0]
                used["last_used_at"] = _now()
                used["updated_at"] = _now()
                _save("jira_credentials.json", jira_credentials)

            _save("jira_servers.json", jira_servers)
            _log_call(endpoint_name, used.get("id") if used else None, 200, None)
            return {"jira_server": srv, "used_credential": used}

        # Non-OAuth credential entry is intentionally not exposed as direct mutation here; tool says mutations are driven by stored sessions.
        # But actions exist only as listed above; any other action would have been caught.

        e = _err("VALIDATION_ERROR", "Unsupported action.")
        _log_call(endpoint_name, None, 400, e["error"]["code"])
        return e

    except Exception as ex:
        # Unexpected condition: return error object (must not raise).
        e = _err("CONFLICT", "Unexpected server error.", detail=str(ex))
        _log_call(endpoint_name, None, 500, e["error"]["code"])
        return e
